#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

void test_case_run() {
    int n;
    ll x, y;
    cin >> n >> x >> y;

    string s;
    cin >> s;
    s = '.'+s;

    ll p[n+1];
    for (int i = 1; i <= n; i++) cin >> p[i];

    if (accumulate(p+1, p+n+1, 0LL) > x+y) {
        cout << "NO\n";
        return;
    }

    if (s == "." + string(n, '0') || s == "." + string(n, '1')) {
        if (s == "." + string(n, '1')) {
            swap(x, y);
        }

        ll x_need = 0;
        for (int i = 1; i <= n; i++) {
            x_need += p[i]/2 + 1;
        }

        if (x < x_need || x < y+n) {
            cout << "NO\n";
        } else {
            cout << "YES\n";
        }

        return;
    }

    ll x_need = 0, y_need = 0;
    for (int i = 1; i <= n; i++) {
        if (s[i] == '0') {
            x_need += p[i]/2 + 1;
        } else {
            y_need += p[i]/2 + 1;
        }
    }
    if (x >= x_need && y >= y_need) cout << "YES\n";
    else cout << "NO\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    cin >> t;
    while (t--) test_case_run();

    return 0;
}

#include <bits/stdc++.h>

using namespace std;
const int INF = 1e9;

void test_first() {
    int n, m;
    cin >> n >> m;

    vector<vector<int>> edge(n+1);
    for (int i = 1; i <= m; i++) {
        int a, b;
        cin >> a >> b;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    vector<int> dist(n+1, INF);
    dist[1] = 0;

    queue<int> bfs;
    bfs.push(1);
    while (!bfs.empty()) {
        int a = bfs.front();
        bfs.pop();

        for (int b : edge[a]) {
            if (dist[b] > dist[a] + 1) {
                dist[b] = dist[a] + 1;
                bfs.push(b);
            }
        }
    }

    for (int i = 1; i <= n; i++) cout << "rgb"[dist[i]%3];
    cout << "\n";
}

void test_second() {
    int dv;
    string color;
    cin >> dv >> color;

    bool fr = false, fg = false, fb = false;
    for (char c : color) {
        if (c == 'r') fr = true;
        if (c == 'g') fg = true;
        if (c == 'b') fb = true;
    }

    if ((int)fr + (int)fg + (int)fb == 1) {
        cout << 1 << "\n";
        return;
    }

    char target;
    if (fr && fg) target = 'g';
    if (fg && fb) target = 'b';
    if (fb && fr) target = 'r';

    for (int i = 0; i < dv; i++) {
        if (color[i] == target) {
            cout << i+1 << "\n";
            return;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string player;
    int t;
    cin >> player >> t;

    if (player == "first") while (t--) test_first();
    else while (t--) {
        int q;
        cin >> q;
        while (q--) test_second();
    }

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

int query(int i, int j) {
    cout << "? " << i << " " << j << endl;
    int ret;
    cin >> ret;
    return ret;
}

void test_case_run() {
    int n;
    cin >> n;

    // Find the first corner
    int dist1[n*n+1];
    for (int i = 1; i <= n*n; i++) dist1[i] = query(1, i);

    int corner1 = 1;
    for (int i = 1; i <= n*n; i++) if (dist1[i] > dist1[corner1]) corner1 = i;

    // Query distance from first corner
    int dist_corner1[n*n+1];
    for (int i = 1; i <= n*n; i++) {
        dist_corner1[i] = query(corner1, i);
    }

    // Find second corner    
    vector<int> corner2_candidates;
    for (int i = 1; i <= n*n; i++) {
        if (dist_corner1[i] == n-1) corner2_candidates.push_back(i);
    }

    int dist_findcorner2[corner2_candidates.size()];
    for (int i = 0; i < corner2_candidates.size(); i++) {
        dist_findcorner2[i] = query(corner2_candidates[0], corner2_candidates[i]); 
    }

    int corner2_index = 0;
    for (int i = 0; i < corner2_candidates.size(); i++) {
        if (dist_findcorner2[i] > dist_findcorner2[corner2_index]) corner2_index = i;
    }

    int corner2 = corner2_candidates[corner2_index];

    // Query distance from second corner
    int dist_corner2[n*n+1];
    for (int i = 1; i <= n*n; i++) {
        dist_corner2[i] = query(corner2, i);
    }

    // Find position
    /*
    d1 = |x-1|+|y-1| = x+y-2
    d2 = |x-1|+|y-n| = x-y+n-1

    d1 + d2 = 2x+n-3 => x = (d1+d2-n+3)/2
    d1 - d2 = 2y-n-1 => y = (d1-d2+n+1)/2
    */
    int ans[n+1][n+1];
    for (int i = 1; i <= n*n; i++) {
        int d1 = dist_corner1[i], d2 = dist_corner2[i];
        int x = (d1+d2-n+3)/2;
        int y = (d1-d2+n+1)/2;
        ans[x][y] = i;
    }

    cout << "!" << endl;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) cout << ans[i][j] << " ";
        cout << endl;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    cin >> t;
    while (t--) test_case_run();

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
using ll = long long;
const int N = 200200;
int qs1[20][N];
ll qs2[20][N];
ll ans[N];
void solve() {
    int n, q;
    cin >> n >> q;
    int sz = 31 - __builtin_clz(n);
    for (int i = 1;i <= n;i++) ans[i] = 0;
    for (int j = 0;j <= sz;j++) {
        for (int i = 0;i <= n;i++) qs1[j][i] = 0, qs2[j][i] = 0;
    }
    while (q--) {
        int l, r;
        cin >> l >> r;
        int sz = 31 - __builtin_clz(r - l + 1);
        for (int j = 0;j <= sz;j++) {
            int k = (r - l + 1) >> j;
            qs1[j][l + (1 << j) - 1]++;
            qs2[j][l + (1 << j) - 1] += l - 1;
            qs1[j][min(n + 1, l + ((k + 1) << j) - 1)]--;
            qs2[j][min(n + 1, l + ((k + 1) << j) - 1)] -= l - 1;
        }
    }
    for (int i = 0;i <= sz;i++) {
        for (int j = 1;j <= n;j++) {
            if (j >= (1 << i)) {
                qs1[i][j] += qs1[i][j - (1 << i)];
                qs2[i][j] += qs2[i][j - (1 << i)];
            }
            ans[j] += 1ll * qs1[i][j] * j * (1 << max(0, i - 1));
            ans[j] -= 1ll * qs2[i][j] * (1 << max(0, i - 1));
        }
    }
    for (int i = 1;i <= n;i++) {
        cout << ans[i] << ' ';
    }
    cout << '\n';
}

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);
    int q;
    cin >> q;
    while (q--) {
        solve();
    }
    return 0;
}
